package com.jnapanam.sportszone.admin.model;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="audit_logs")public class AuditLog{@Id private UUID id;@Column(name="actor_user_id")private UUID actorUserId;@Column(name="http_method",nullable=false,length=10)private String httpMethod;@Column(name="request_path",nullable=false,length=300)private String requestPath;@Column(name="response_status",nullable=false)private int responseStatus;@Column(name="remote_address",length=80)private String remoteAddress;@Column(name="occurred_at",nullable=false)private Instant occurredAt;protected AuditLog(){}public AuditLog(UUID actor,String method,String path,int status,String remote){id=UUID.randomUUID();actorUserId=actor;httpMethod=method;requestPath=path;responseStatus=status;remoteAddress=remote;occurredAt=Instant.now();}public UUID getId(){return id;}public UUID getActorUserId(){return actorUserId;}public String getHttpMethod(){return httpMethod;}public String getRequestPath(){return requestPath;}public int getResponseStatus(){return responseStatus;}public String getRemoteAddress(){return remoteAddress;}public Instant getOccurredAt(){return occurredAt;}}
